import{_ as e,o as a,c as r,ag as d}from"./chunks/framework.DMXcdKmJ.js";const m=JSON.parse('{"title":"创建和管理工程部署","description":"在运维管理选择工程模式、版本、运行环境、节点和访问方式，确认部署及后续启停操作。","frontmatter":{"title":"创建和管理工程部署","description":"在运维管理选择工程模式、版本、运行环境、节点和访问方式，确认部署及后续启停操作。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/deployments.md","filePath":"zh/使用指南/创建和管理工程部署.md"}'),o={name:"zh/guide/deployments.md"};function n(h,t,i,l,s,p){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="创建和管理工程部署" tabindex="-1">创建和管理工程部署 <a class="header-anchor" href="#创建和管理工程部署" aria-label="Permalink to &quot;创建和管理工程部署&quot;">​</a></h1><p>“部署”是把选定内容安排到目标环境运行，不只是保存文件。相关名词见<a href="/induframe-docs/zh/concepts/environments-and-nodes.html">运行环境和节点</a>与<a href="/induframe-docs/zh/reference/glossary.html">术语解释</a>。</p><p>从 **“运维管理” → “工程部署”**操作。开始前，需要相应工程和部署权限、可用运行环境，以及已就绪的节点、基础服务和采集连接落点。</p><p>业务正在运行时，先与负责人安排替换、停机与数据保护，不为试用界面替换现有部署。</p><h2 id="_1-选择工程内容" tabindex="-1">1. 选择工程内容 <a class="header-anchor" href="#_1-选择工程内容" aria-label="Permalink to &quot;1. 选择工程内容&quot;">​</a></h2><p>正式版本的准备步骤见<a href="/induframe-docs/zh/guide/project-releases.html">发布工程版本</a>，环境统一地址的设置见<a href="/induframe-docs/zh/guide/environment-entry.html">访问入口</a>。</p><p>点击 <strong>“创建工程部署”</strong>，选择正确工程及模式：</p><table tabindex="0"><thead><tr><th>模式</th><th>采用什么内容</th></tr></thead><tbody><tr><td>开发模式</td><td>从当前工程内容构建开发快照，不需要选择正式发布版本</td></tr><tr><td>生产模式</td><td>选择已经发布的正式工程版本</td></tr></tbody></table><p>开发模式也会创建实际运行部署，不是浏览器里的实时预览。提交后不会因为继续修改源码而自动更新运行内容。</p><p>生产模式没有可选版本时，先到工程管理的 **“发布工程”**准备版本，再回来选择；不要为了继续而随意换成另一个工程。</p><h2 id="_2-选择环境、节点与访问方式" tabindex="-1">2. 选择环境、节点与访问方式 <a class="header-anchor" href="#_2-选择环境、节点与访问方式" aria-label="Permalink to &quot;2. 选择环境、节点与访问方式&quot;">​</a></h2><ol><li>选择目标运行环境。</li><li>按实际需要的运行引擎选择兼容且就绪的节点。</li><li>核对工业采集连接在该环境的部署节点，缺少时按提示“去数据中心配置”。</li><li>选择至少一种访问方式，核对地址与端口安排。</li></ol><p>“环境入口”要求该环境先启用统一访问入口；“节点直连”使用部署节点的独立地址和端口。两者可以同时启用，不是二选一。</p><p>端口已占用、节点资格待刷新或能力不匹配时，先处理提示。不要用任意节点或空白端口绕过检查。</p><h2 id="_3-提交并等待实际就绪" tabindex="-1">3. 提交并等待实际就绪 <a class="header-anchor" href="#_3-提交并等待实际就绪" aria-label="Permalink to &quot;3. 提交并等待实际就绪&quot;">​</a></h2><p>确认后，按当前模式点击 **“部署开发模式”**或 <strong>“部署生产版本”</strong>。已有同工程、同环境部署时，界面会提示替换并使用“更新部署”，应先确认影响。</p><p>构建和部署期间等待结果，不连续重试。代码构建失败时，使用“去应用开发修复”检查源码；等待超时或结果不明确时先查部署列表和记录，避免重复替换。</p><p>成功提交只表示任务已受理。继续核对运行状态、各引擎健康和部署详情，再从可用的实际入口打开页面，验证工程用户、数据及业务功能。</p><h2 id="_4-分清日常操作" tabindex="-1">4. 分清日常操作 <a class="header-anchor" href="#_4-分清日常操作" aria-label="Permalink to &quot;4. 分清日常操作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>影响</th></tr></thead><tbody><tr><td>启动、停止</td><td>改变现有部署的运行状态；停止后工程可能不可访问</td></tr><tr><td>重启</td><td>重启现有运行服务，不意味着升级代码或版本</td></tr><tr><td>重新部署</td><td>重新下发当前制品，不构建最新开发快照，也不升级发布版本</td></tr><tr><td>更新部署</td><td>重新选择并提交工程内容，核对替换确认</td></tr><tr><td>删除部署</td><td>清理运行资源和运行态消息、释放端口，不删除工程设计和发布版本</td></tr></tbody></table><p>因此，<strong>“重新部署”不是“应用最新代码”</strong>。需要使用新源码或新版本时，应按更新部署流程明确选择内容。</p><p>操作前核对目标、影响与确认框；操作后检查<a href="/induframe-docs/zh/guide/operations-records.html">运维记录</a>和实际运行结果，不把请求已提交当作完成。</p><h2 id="遇到问题" tabindex="-1">遇到问题 <a class="header-anchor" href="#遇到问题" aria-label="Permalink to &quot;遇到问题&quot;">​</a></h2><p>先保留工程、环境、版本或模式、操作时间和错误。状态过期时等待重新同步；入口不可用时分别检查运行、引擎健康、访问开关和网络，不仅凭一个状态图标判断。</p><p>下一步：<a href="/induframe-docs/zh/guide/runtime-environments.html">运行环境</a> · <a href="/induframe-docs/zh/guide/operations-records.html">运维记录</a> · <a href="/induframe-docs/zh/concepts/development-and-runtime.html">开发与运行的区别</a>。</p>',25)])])}const _=e(o,[["render",n]]);export{m as __pageData,_ as default};
